    Assert.assertNull(jsonMap.get("foo.bar1"));
    Assert.assertNull(jsonMap.get("baz"));
    Assert.assertNull(jsonMap.get("blah"));
    Assert.assertNull(jsonMap.get("nested-foo.bar1"));
