    aggregateBuffer(selector, agg, buf, position);
    Assert.assertArrayEquals(new long[] { 0, 0, 0, 0, 1, 0 }, ((Histogram) agg.get(buf, position)).bins);
    Assert.assertArrayEquals(new long[] { 0, 0, 0, 0, 1, 0 }, ((Histogram) agg.get(buf, position)).bins);
