@Test
public void basicTest() {
    // a b c d e f
    // 0 2 3 4
    String[] s1 = { "a", "c", "d", "e" };
    // 1 2 4
    String[] s2 = { "b", "c", "e" };
    // 0 3 5
    String[] s3 = { "a", "d", "f" };
    String[] s4 = { "a", "b", "c" };
    String[] s5 = { "a", "b", "c", "d", "e", "f" };
    Indexed<String> i1 = new ArrayIndexed<String>(s1, String.class);
    Indexed<String> i2 = new ArrayIndexed<String>(s2, String.class);
    Indexed<String> i3 = new ArrayIndexed<String>(s3, String.class);
    Indexed<String> i4 = new ArrayIndexed<String>(s4, String.class);
    Indexed<String> i5 = new ArrayIndexed<String>(s5, String.class);
    IndexMerger.DictionaryMergeIterator iterator = new IndexMerger.DictionaryMergeIterator(new Indexed[] { i1, i2, i3, i4, i5 }, false);
    Assert.assertArrayEquals(new String[] { "a", "b", "c", "d", "e", "f" }, Iterators.toArray(iterator, String.class));
    Assert.assertArrayEquals(new int[] { 0, 2, 3, 4 }, iterator.conversions[0].array());
    Assert.assertArrayEquals(new int[] { 1, 2, 4 }, iterator.conversions[1].array());
    Assert.assertArrayEquals(new int[] { 0, 3, 5 }, iterator.conversions[2].array());
    Assert.assertArrayEquals(new int[] { 0, 1, 2 }, iterator.conversions[3].array());
    Assert.assertArrayEquals(new int[] { 0, 1, 2, 3, 4, 5 }, iterator.conversions[4].array());
    Assert.assertTrue(iterator.needConversion(0));
    Assert.assertTrue(iterator.needConversion(1));
    Assert.assertTrue(iterator.needConversion(2));
    Assert.assertFalse(iterator.needConversion(3));
    Assert.assertFalse(iterator.needConversion(4));
}

@Test
public void testEmptyIndex() throws Exception {
    File tmpDir = File.createTempFile("emptyIndex", "");
    if (!tmpDir.delete()) {
        throw new IllegalStateException("tmp delete failed");
    }
    if (!tmpDir.mkdir()) {
        throw new IllegalStateException("tmp mkdir failed");
    }
    try {
        IncrementalIndex emptyIndex = new OnheapIncrementalIndex(0, QueryGranularities.NONE, new AggregatorFactory[0], 1000);
        IncrementalIndexAdapter emptyIndexAdapter = new IncrementalIndexAdapter(new Interval("2012-08-01/P3D"), emptyIndex, new ConciseBitmapFactory());
        TestHelper.getTestIndexMerger().merge(Lists.<IndexableAdapter>newArrayList(emptyIndexAdapter), true, new AggregatorFactory[0], tmpDir, new IndexSpec());
        QueryableIndex emptyQueryableIndex = TestHelper.getTestIndexIO().loadIndex(tmpDir);
        Assert.assertEquals("getDimensionNames", 0, Iterables.size(emptyQueryableIndex.getAvailableDimensions()));
        Assert.assertEquals("getMetricNames", 0, Iterables.size(emptyQueryableIndex.getColumnNames()));
        Assert.assertEquals("getDataInterval", new Interval("2012-08-01/P3D"), emptyQueryableIndex.getDataInterval());
        Assert.assertEquals("getReadOnlyTimestamps", 0, emptyQueryableIndex.getColumn(Column.TIME_COLUMN_NAME).getLength());
    } finally {
        FileUtils.deleteDirectory(tmpDir);
    }
}

