@Test
public void testUnplannableQueries() throws Exception {
    // All of these queries are unplannable because they rely on features Druid doesn't support.
    // This test is here to confirm that we don't fall back to Calcite's interpreter or enumerable implementation.
    // It's also here so when we do support these features, we can have "real" tests for these queries.
    final List<String> queries = ImmutableList.of(// Concat two dims
    "SELECT (dim1 || ' ' || dim2) AS cc, COUNT(*) FROM druid.foo GROUP BY dim1 || ' ' || dim2", // SELECT query with order by
    "SELECT dim1 FROM druid.foo ORDER BY dim1", // TRIM function
    "SELECT TRIM(dim1) FROM druid.foo", // Filter on two columns equaling each other
    "SELECT COUNT(*) FROM druid.foo WHERE dim1 = dim2", // Similar to above
    "SELECT COUNT(*) FROM druid.foo WHERE CHARACTER_LENGTH(dim1) = CHARACTER_LENGTH(dim2)", // Group by math
    "SELECT CHARACTER_LENGTH(dim1) + 1 FROM druid.foo GROUP BY CHARACTER_LENGTH(dim1) + 1", // Self-join
    "SELECT COUNT(*) FROM druid.foo x, druid.foo y", // Project a dimension from GROUP BY
    "SELECT SUBSTRING(dim1, 2) FROM druid.foo GROUP BY dim1", // ORDER BY projection
    "SELECT dim1 FROM druid.foo GROUP BY dim1 ORDER BY SUBSTRING(dim1, 2)");
    for (final String query : queries) {
        assertQueryIsUnplannable(query);
    }
}

