@Test
public void testUsingSubqueryAsFilter() throws Exception {
    testQuery(// Sanity check; this query should work with a single level of nesting.
    PLANNER_CONFIG_SINGLE_NESTING_ONLY, "SELECT dim1, dim2, COUNT(*) FROM druid.foo " + "WHERE dim2 IN (SELECT dim1 FROM druid.foo WHERE dim1 <> '')" + "AND dim1 <> 'xxx'" + "group by dim1, dim2 ORDER BY dim2", ImmutableList.<Query>of(GroupByQuery.builder().setDataSource(CalciteTests.DATASOURCE1).setInterval(QSS(Filtration.eternity())).setGranularity(QueryGranularities.ALL).setDimFilter(NOT(SELECTOR("dim1", "", null))).setDimensions(DIMS(new DefaultDimensionSpec("dim1", "d0"))).setContext(QUERY_CONTEXT_DEFAULT).build(), GroupByQuery.builder().setDataSource(CalciteTests.DATASOURCE1).setInterval(QSS(Filtration.eternity())).setGranularity(QueryGranularities.ALL).setDimFilter(AND(IN("dim2", ImmutableList.of("1", "10.1", "2", "abc", "def"), null), NOT(SELECTOR("dim1", "xxx", null)))).setDimensions(DIMS(new DefaultDimensionSpec("dim2", "d1"), new DefaultDimensionSpec("dim1", "d0"))).setAggregatorSpecs(AGGS(new CountAggregatorFactory("a0"))).setLimitSpec(new DefaultLimitSpec(ImmutableList.of(new OrderByColumnSpec("d1", OrderByColumnSpec.Direction.ASCENDING)), Integer.MAX_VALUE)).setContext(QUERY_CONTEXT_DEFAULT).build()), ImmutableList.of(new Object[] { "def", "abc", 1L }));
}

