@Test
public void testUnicodeFilterAndGroupBy() throws Exception {
    testQuery("SELECT
" + "  dim1,
" + "  dim2,
" + "  COUNT(*)
" + "FROM foo2
" + "WHERE
" + // First char is actually in the string; second is a SQL U& escape
    "  dim1 LIKE U&'ד\05E8%'
" + "  OR dim1 = 'друид'
" + "GROUP BY dim1, dim2", ImmutableList.<Query>of(GroupByQuery.builder().setDataSource(CalciteTests.DATASOURCE2).setInterval(QSS(Filtration.eternity())).setGranularity(QueryGranularities.ALL).setDimFilter(OR(new LikeDimFilter("dim1", "דר%", null, null), new SelectorDimFilter("dim1", "друид", null))).setDimensions(DIMS(new DefaultDimensionSpec("dim1", "d0"), new DefaultDimensionSpec("dim2", "d1"))).setAggregatorSpecs(AGGS(new CountAggregatorFactory("a0"))).setContext(QUERY_CONTEXT_DEFAULT).build()), ImmutableList.of(new Object[] { "друид", "ru", 1L }, new Object[] { "דרואיד", "he", 1L }));
}

